document.addEventListener('click',async event=>{let b=event.target.closest('button');if(!b)return;if(b.dataset.view){show(b.dataset.view);return}let a=b.dataset.action;if(!a)return;if(a==='history'){$('history-agent').value=b.dataset.agent;historyOffset=0;show('history');loadHistory();return}if(a==='waiting-open'){openWaiting.add(b.dataset.item);renderWaiting(current);return}if(a==='waiting-close'){openWaiting.delete(b.dataset.item);renderWaiting(current);return}if(a==='waiting-send'){await sendWaiting(b);return}if(a==='restart'){let name=b.dataset.agent;confirmAction('Restart '+name+'?', 'The supervisor will test and release the shared runtime, including all agents and the dashboard. Active work finishes first.',()=>action('/api/restart',{agent:name}));return}if(a==='cancel'||a==='resume'){confirmAction(a==='cancel'?'Cancel this task?':'Resume this task?',b.dataset.title+(a==='resume'?' — review saved results and prior actions first. Resuming can repeat side effects and incur model charges.':' — cancellation takes effect at the next safe model/tool boundary.'),()=>action('/api/task',{task:Number(b.dataset.task),agent:b.dataset.agent,action:a}))}else if(a==='result'){try{let d=await api('/api/result?agent='+encodeURIComponent(b.dataset.agent)+'&task='+encodeURIComponent(b.dataset.task));$('detail-title').textContent=b.dataset.title;$('detail-text').textContent=d.text;$('detail').showModal()}catch(e){toast(e.message,true)}}else if(a==='trace'){try{let d=await api('/api/trace?agent='+encodeURIComponent(b.dataset.agent)+'&task='+encodeURIComponent(b.dataset.task));$('detail-title').textContent='Trace · '+b.dataset.title;$('detail-text').textContent=traceText(d);$('detail').showModal()}catch(e){toast(e.message,true)}}});
function traceText(d){let s=d.summary,t0=d.events.length?d.events[0].t:0,lines=[`task ${d.task} · ${d.status} · ${s.tool_calls} tool calls (${s.failed_tools} failed) · ${s.model_calls} model calls · ${s.tokens??'unknown'} provider-reported tokens · ${s.bounces} bounces · ${s.minutes} min`,''];for(let e of d.events){let dt=((e.t-t0)/60).toFixed(1).padStart(6)+'m',tag=e.kind==='tool'?e.name:e.kind==='model'?'model '+e.name:e.kind,st=e.status==='finished'||e.status==='response'?'':' ['+e.status+']';lines.push(`${dt}  ${tag}${st}  ${e.detail||''}${e.kind==='tool'?'  → '+e.size+' chars'+(e.archive?' (archived)':''):e.kind==='model'?'  '+(e.size??'unknown')+' tok':''}${e.error?'  ! '+e.error:''}`)}if(!d.events.length)lines.push('No receipts for this task.');return lines.join(String.fromCharCode(10))}
