async function loadHistory(){let version=++historyVersion;historyLoaded=true;const params=historyParams();$('history-count').textContent='Loading locally saved messages…';try{let data=await api('/api/history?'+params);if(version!==historyVersion)return;$('history-note').textContent=data.note+' Downloads are saved by your browser.';$('history-count').textContent=number(data.count)+' matching messages · newest first';$('history-messages').replaceChildren(...(data.messages.length?data.messages.map(row=>{let card=el('article',undefined,'history-message');let head=el('div',undefined,'history-message-head');if(row.role!=='user'){let photo=el('img');photo.src='/assets/'+data.agent+'.jpg';photo.alt='';head.append(photo)}head.append(el('strong',row.role==='user'?'Alex':agentNames[data.agent]),el('time',row.time?row.time.replace('T',' '):'Time unknown'));let body=el('div',row.text,'message-body');card.append(head,body);if(row.role==='assistant')card.append(el('small','Time associated with the user’s turn; delivery time is not recorded.','muted'));if(row.truncated)card.append(el('small','Preview shortened. Download to read the full text.','muted'));return card}):[el('div','No retained messages match these filters.','empty')]));$('history-prev').disabled=data.offset===0;$('history-next').disabled=!data.has_more;$('history-page').textContent=data.count?number(data.offset+1)+'–'+number(Math.min(data.offset+30,data.count))+' of '+number(data.count):'No results'}catch(e){if(version!==historyVersion)return;$('history-count').textContent='History could not be loaded.';$('history-messages').replaceChildren(el('div',e.message,'notice danger'));$('history-prev').disabled=$('history-next').disabled=true}}
