async function downloadHistory(format){const params=historyParams();params.delete('offset');params.set('format',format);const b=$(format==='md'?'export-md':'export-json');b.disabled=true;try{let r=await fetch('/api/history/export?'+params,{cache:'no-store'});if(!r.ok){let e=await r.json();throw Error(e.error||'Export unavailable')}let blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=params.get('agent')+'-history-'+new Date().toISOString().slice(0,10)+'.'+format;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('History download prepared. Your browser controls where it is saved.')}catch(e){toast(e.message,true)}finally{b.disabled=false}}
