function hhmm(ts){try{let d=new Date(ts);return isNaN(d)?String(ts).slice(11,16):d.toTimeString().slice(0,5)}catch(e){return String(ts).slice(11,16)}}
function who(n){return {coordinator:'Cato',cal:'Cal',vit:'Vit'}[n]||n}
function card(cls,title,time){let c=el('article',undefined,'comm-card '+(cls||''));let h=el('div',undefined,'comm-head');h.append(el('strong',title));if(time)h.append(el('span',time,'muted'));c.append(h);return c}
function prose(text,cls){let p=el('p',text||'','comm-prose '+(cls||''));return p}
function raw(obj,label){let d=el('details',undefined,'comm-raw');d.append(el('summary',label||'raw'),el('pre',JSON.stringify(obj,null,2)));return d}
function headerLines(text){let out={},rest=[];for(let line of String(text||'').split('\n')){let m=line.match(/^\s*(DONE|OPEN|EVIDENCE|COST)\s*:\s*(.*)$/);if(m&&!(m[1] in out))out[m[1]]=m[2];else rest.push(line)}return {fields:out,rest:rest.join('\n').trim()}}
function renderConversation(d,row){let events=d.events||[],nodes=[];let submit=events.find(e=>e.action==='submit'&&e.phase==='intent');let req=submit&&submit.request||{};let returns=events.filter(e=>e.phase==='return');let last=returns.length?returns[returns.length-1]:null;let lastResp=last&&last.response&&typeof last.response==='object'?last.response:{};let acc=d.acceptance||{};
 /* 1. summary */
 let sum=card('comm-summary',req.title||row.title||row.request_id);let meta=el('div',undefined,'comm-meta');meta.append(badge(acc.status==='read'?'accepted':(lastResp.status||row.status||'unobserved')));meta.append(el('span','Cato → '+who(row.agent)+(acc.source?' · '+acc.source.replace('_',' '):''),'muted'));if(acc.purpose)meta.append(el('span','Why: '+acc.purpose,'muted'));let b=lastResp.budget||{};if(b.effective_spent!=null)meta.append(el('span','Cost '+number(b.effective_spent)+(b.cap?' of target '+number(b.cap):'')+' effective tokens · '+(b.turns||0)+' turns','muted'));meta.append(el('span',row.request_id,'muted mono'));sum.append(meta);nodes.push(sum);
 /* 2. brief */
 if(submit){let c=card('comm-brief','Brief from Cato · '+hhmm(submit.timestamp));c.append(prose(req.question||req.scope||submit.request_raw||''));let items=req.completion_items||[];if(items.length){c.append(el('p','Done means:','comm-label'));let ol=el('ol',undefined,'comm-items');items.forEach(it=>{let li=el('li');li.append(el('span',(it.critical?'critical · ':'')+it.item));if(it.check)li.append(el('span',' check: '+it.check,'muted'));ol.append(li)});c.append(ol)}let facts=[];if(req.budget_effective_tokens)facts.push('Target '+number(req.budget_effective_tokens)+' effective tokens');if(req.depth)facts.push('Stop rule: '+req.depth);if(req.output_path)facts.push('Output: '+req.output_path);if(req.allowed_paths)facts.push('Allowed paths: '+req.allowed_paths.join(', '));if(facts.length)c.append(prose(facts.join('\n'),'muted'));c.append(raw(req,'raw brief'));nodes.push(c)}
 /* 3. progress: collapse status polls */
 let polls=returns.filter(e=>e.action==='status');if(polls.length){let seq=[];for(let e of polls){let st=(e.response&&e.response.status)||'?';if(seq[seq.length-1]!==st)seq.push(st)}let c=card('comm-progress','Progress · '+hhmm(polls[0].timestamp)+'–'+hhmm(polls[polls.length-1].timestamp));c.append(prose(seq.join(' → ')+' · status polled '+polls.length+' times by the runtime'));let qs=polls.filter(e=>e.response&&e.response.question);if(qs.length){c.append(prose('Question from '+who(row.agent)+': '+qs[qs.length-1].response.question,'comm-question'))}let cps=polls.map(e=>e.response&&e.response.checkpoint).filter(Boolean);if(cps.length){try{let cp=JSON.parse(cps[cps.length-1]);let line=[];if(cp.completed)line.push('Completed: '+cp.completed);if(cp.next_action)line.push('Next: '+cp.next_action);if(cp.items_done&&cp.items_done.length)line.push('Items done: '+cp.items_done.join(', '));if(cp.blocker)line.push('Blocker: '+cp.blocker);c.append(prose(line.join('\n'),'muted'))}catch(e){}}nodes.push(c)}
 /* 4. other actions between */
 for(let e of events){if(e.phase!=='intent'||['submit','status','result'].includes(e.action))continue;let c=card('comm-action',who(e.sender)+' → '+who(e.recipient)+' · '+e.action,hhmm(e.timestamp));let r=e.request||{};let text=r.note||e.message||r.budget_effective_tokens&&('New target '+number(r.budget_effective_tokens))||'';if(r.items)text+=(text?'\n':'')+'Items: '+r.items.join(', ');if(r.completion_items)text+=(text?'\n':'')+'New items: '+r.completion_items.map(i=>i.item).join('; ');c.append(prose(text||'(no text)'));let ret=events.find(x=>x.phase==='return'&&x.operation_id===e.event_id);if(ret&&ret.response&&ret.response.status)c.append(el('span',undefined)).append(badge(ret.response.status));nodes.push(c)}
 /* 5. result */
 let res=returns.filter(e=>e.action==='result'&&e.response&&e.response.text);if(res.length){let e=res[res.length-1];let h=headerLines(e.response.text);let c=card('comm-result','Result from '+who(row.agent)+' · '+hhmm(e.timestamp));let keys=['DONE','OPEN','EVIDENCE','COST'].filter(k=>k in h.fields);if(keys.length){let dl=el('dl',undefined,'comm-header');keys.forEach(k=>{dl.append(el('dt',k),el('dd',h.fields[k]))});c.append(dl)}if(h.rest){let det=el('details',undefined,'comm-text');det.append(el('summary','Full result ('+number(h.rest.length)+' characters)'),prose(h.rest));if(!keys.length)det.open=true;c.append(det)}if(e.response.result_path)c.append(prose('Saved at '+e.response.result_path,'muted'));nodes.push(c)}
 /* 6. failures */
 for(let e of events){if(e.phase==='failure'||(e.phase==='return'&&e.returncode&&e.returncode!==0)){let c=card('comm-failure','Failed · '+e.action,hhmm(e.timestamp));c.append(prose(e.error||(e.response&&e.response.error)||e.stderr||'see raw'));nodes.push(c)}}
 /* 7. acceptance */
 if(acc.verdicts&&acc.verdicts.length||acc.scorecard){let c=card('comm-accept','Acceptance by Cato'+(acc.updated?' · '+hhmm(new Date(acc.updated*1000).toISOString()):''));if(acc.verdicts&&acc.verdicts.length){let t=el('table',undefined,'comm-verdicts');let th=el('tr');['Item','Verdict','Evidence'].forEach(x=>th.append(el('th',x)));t.append(th);acc.verdicts.forEach(v=>{let tr=el('tr');tr.append(el('td',String(v.item)));let td=el('td');td.append(badge(v.verdict==='met'?'met':v.verdict==='partial'?'partial':'not met'));tr.append(td);tr.append(el('td',v.evidence||''));t.append(tr)});c.append(t)}let sc=acc.scorecard||{};if(sc.critical_total!=null)c.append(prose('Critical items met '+(sc.critical_met||0)+' of '+sc.critical_total+' · all items '+(sc.items_met||0)+' of '+sc.items_total+(sc.reworks?' · reworks '+sc.reworks:''),'muted'));if(sc.brief_lesson)c.append(prose('Brief lesson: '+sc.brief_lesson,'comm-lesson'));nodes.push(c)}else if(acc.status){nodes.push(card('comm-accept','Not yet accepted by Cato ('+acc.status+')'))}
 /* 8. raw everything */
 let r=el('details',undefined,'comm-raw comm-raw-all');r.append(el('summary','All '+events.length+' recorded events and the saved snapshot, raw'),el('pre',JSON.stringify({events:events,snapshots:d.snapshots||[],acceptance:d.acceptance||null},null,2)));nodes.push(r);return nodes}
